import{_ as i,o as a,c as t,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/sekundarstufen/tutorials-sprachpruefungen-fach-anlegen.png",l="/bilder/sekundarstufen/schueler-sprachenfolgen-fsp.png",h="/bilder/sekundarstufen/schueler-fsp-leistungsdaten-fach-hinzufuegen.png",z=JSON.parse('{"title":"Sprachfeststellungsprüfungen als Fremdsprachenersatz erfassen","description":"","frontmatter":{"title":"Sprachfeststellungsprüfungen als Fremdsprachenersatz erfassen","source_pageid":1436,"source_revision":6084},"headers":[],"relativePath":"zeugnisse/sekundarstufen/sprachpruefung-feststellungspruefung-anstelle-von-pflicht-oder-wahlpflichtfremdsprachen-tutorial.md","filePath":"zeugnisse/sekundarstufen/sprachpruefung-feststellungspruefung-anstelle-von-pflicht-oder-wahlpflichtfremdsprachen-tutorial.md"}'),d={name:"zeugnisse/sekundarstufen/sprachpruefung-feststellungspruefung-anstelle-von-pflicht-oder-wahlpflichtfremdsprachen-tutorial.md"};function g(c,s,o,p,f,m){return a(),t("div",null,[...s[0]||(s[0]=[r(`<h1 id="sprachfeststellungsprufungen-als-fremdsprachenersatz-erfassen" tabindex="-1">Sprachfeststellungsprüfungen als Fremdsprachenersatz erfassen <a class="header-anchor" href="#sprachfeststellungsprufungen-als-fremdsprachenersatz-erfassen" aria-label="Permalink to &quot;Sprachfeststellungsprüfungen als Fremdsprachenersatz erfassen&quot;">​</a></h1><p>Erfassen Sie Sprachprüfungen, die eine Pflicht- oder Wahlpflichtfremdsprache ersetzen. Unterscheiden Sie die ersetzte Sprache, die Zeugnisart und die im Artikel beschriebenen Ausnahmen.</p><p>Dieser Artikel behandelt die <strong>Sprachprüfung (Feststellungsprüfung) anstelle von Pflichtfremdsprachen oder Wahlpflichtfremdsprachen nach BASS 13-61 Nr. 1</strong>.</p><p><strong>Zielgruppe:</strong></p><ul><li>Die Sekundarstufe I der deutschen Schule wurde nicht von Beginn an besucht und</li><li>eine Eingliederung in das Sprachenangebot der Schule konnte nicht erfolgen und</li><li>die Amtssprache des Herkunftslandes konnte nicht anstelle einer Pflicht- oder Wahlpflichtfremdsprache weitergeführt werden.</li></ul><p><strong>Ersatz:</strong> Die Sprachprüfung ersetzt</p><ul><li>die erste Pflichtfremdsprache (Englisch) oder</li><li>die zweite Pflichtfremdsprache oder</li><li>die dritte Wahlpflichtfremdsprache.</li></ul><p>Das Ergebnis ist vollumfänglich versetzungs- und abschlussrelevant.</p><h2 id="anstelle-der-1-fremdsprache-englisch" tabindex="-1">Anstelle der 1. Fremdsprache Englisch <a class="header-anchor" href="#anstelle-der-1-fremdsprache-englisch" aria-label="Permalink to &quot;Anstelle der 1. Fremdsprache Englisch&quot;">​</a></h2><p>Soll eine Amtssprache Englisch ersetzen, so nehmen die Schülerinnen und Schüler im Rahmen der Möglichkeiten am Regelunterricht oder an einem den Regelunterricht ergänzenden Unterricht im Fach Englisch teil.</p><p>Die Teilnahme am Englischunterricht wird auf den Zeugnissen der Sekundarstufe I unter Bemerkungen dokumentiert.</p><h3 id="zeugnisbemerkungen" tabindex="-1">Zeugnisbemerkungen <a class="header-anchor" href="#zeugnisbemerkungen" aria-label="Permalink to &quot;Zeugnisbemerkungen&quot;">​</a></h3><h4 id="zeugnisse-innerhalb-der-si-bei-erganzender-teilnahme-am-englischunterricht" tabindex="-1">Zeugnisse innerhalb der SI bei ergänzender Teilnahme am Englischunterricht <a class="header-anchor" href="#zeugnisse-innerhalb-der-si-bei-erganzender-teilnahme-am-englischunterricht" aria-label="Permalink to &quot;Zeugnisse innerhalb der SI bei ergänzender Teilnahme am Englischunterricht&quot;">​</a></h4><p>Das Fach Englisch kann auf dem Zeugnis aufgenommen werden.</p><p>Als Note wird dann <em>&quot;Teilgenommen&quot;</em> eingetragen.</p><p>Als Zeugnisbemerkung wird zum Beispiel folgendes eingetragen:</p><pre><code> &quot;$Vorname$ hat am Unterricht im Fach Englisch teilgenommen.&quot;
</code></pre><h4 id="abschlusszeugnis-oder-versetzungszeugnis-ende-der-si-im-prufungsjahr" tabindex="-1">Abschlusszeugnis oder Versetzungszeugnis Ende der SI im Prüfungsjahr <a class="header-anchor" href="#abschlusszeugnis-oder-versetzungszeugnis-ende-der-si-im-prufungsjahr" aria-label="Permalink to &quot;Abschlusszeugnis oder Versetzungszeugnis Ende der SI im Prüfungsjahr&quot;">​</a></h4><p>Die Prüfungsnote wird von der Schule, der Einrichtung der Weiterbildung beziehungsweise der besonderen Einrichtung des Schulwesens anstelle der 1. Fremdsprache in das Abschlusszeugnis bzw. in das Versetzungszeugnis übertragen.</p><p>In der Spalte Bemerkungen ist aufzunehmen:</p><pre><code> &quot;Die Note in SPRACHE wurde aufgrund der Sprachprüfung gemäß RdErl. d. KM v. 10.03.1992 (BASS 13-61 Nr. 1) erteilt.&quot;
</code></pre><h4 id="abschlusszeugnis-und-abgangszeugnis-ende-der-sekundarstufe-i" tabindex="-1">Abschlusszeugnis und Abgangszeugnis Ende der Sekundarstufe I <a class="header-anchor" href="#abschlusszeugnis-und-abgangszeugnis-ende-der-sekundarstufe-i" aria-label="Permalink to &quot;Abschlusszeugnis und Abgangszeugnis Ende der Sekundarstufe I&quot;">​</a></h4><p>Ein GeR-Referenzniveau darf nur entsprechend dem vorliegenden Nachweis und den einschlägigen Zeugnisvorgaben eingetragen werden. Für einen nachgewiesenen MSA-Prüfungsfall kann die folgende Bemerkung verwendet werden:</p><p>In der Spalte Bemerkungen ist aufzunehmen:</p><pre><code> &quot;Das für SPRACHE ausgewiesene Niveau wurde durch eine Sprachprüfung auf dem Anspruchsniveau des Mittleren Schulabschlusses (Fachoberschulreife) in Klasse 10 erreicht.&quot;
</code></pre><h4 id="abschluss-oder-versetzungszeugnis-am-ende-der-ef-je-nach-laufbahn" tabindex="-1">Abschluss- oder Versetzungszeugnis am Ende der EF je nach Laufbahn <a class="header-anchor" href="#abschluss-oder-versetzungszeugnis-am-ende-der-ef-je-nach-laufbahn" aria-label="Permalink to &quot;Abschluss- oder Versetzungszeugnis am Ende der EF je nach Laufbahn&quot;">​</a></h4><p>Die Prüfungsnote wird von der Schule, der Einrichtung der Weiterbildung bzw. der besonderen Einrichtung des Schulwesens anstelle der 2. oder 3. Wahlpflichtfremdsprache in das Abschlusszeugnis bzw. in das Versetzungszeugnis übertragen.</p><p>In der Spalte Bemerkungen ist aufzunehmen:</p><pre><code> &quot;Die Note in SPRACHE wurde aufgrund der Sprachprüfung gemäß RdErl. d. KM v. 10.03.1992 (BASS 13-61 Nr. 1) erteilt.&quot;
</code></pre><h4 id="abiturzeugnis" tabindex="-1">Abiturzeugnis <a class="header-anchor" href="#abiturzeugnis" aria-label="Permalink to &quot;Abiturzeugnis&quot;">​</a></h4><p>Übernehmen Sie unter Fremdsprachen das nachgewiesene GeR-Niveau nach den geltenden Zeugnisvorgaben. Aus der Feststellungsprüfung darf hier nicht pauschal B1 abgeleitet werden. Die folgende Bemerkung setzt den darin beschriebenen Nachweis voraus:</p><p>In der Spalte Bemerkungen ist aufzunehmen:</p><pre><code> &quot;Das für SPRACHE ausgewiesene Niveau wurde durch eine Sprachprüfung in Klasse 10 erreicht.&quot;
</code></pre><h3 id="prufungsbescheinigung" tabindex="-1">Prüfungsbescheinigung <a class="header-anchor" href="#prufungsbescheinigung" aria-label="Permalink to &quot;Prüfungsbescheinigung&quot;">​</a></h3><p>Schülerinnen und Schüler, die sich der Sprachprüfung unterzogen haben, erhalten eine Bescheinigung nach dem Muster der Anlage 1 BASS 13-61 Nr. 1. Dort ist dokumentiert, an welche Stelle die geprüfte Sprache tritt.</p><p>Die Bescheinigung weist Anspruchsniveau, Ergebnis und ersetzte Fremdsprache aus. Englisch-Nachweise aus einer zusätzlichen ZP10 sind davon zu unterscheiden; siehe <a href="https://bass.schule.nrw/257.htm" target="_blank" rel="noreferrer">BASS 13-61 Nr. 1, Nummern 9 und 10</a>.</p><h3 id="zp10" tabindex="-1">ZP10 <a class="header-anchor" href="#zp10" aria-label="Permalink to &quot;ZP10&quot;">​</a></h3><p>Am Ende der Sekundarstufe I ermöglicht die Schule diesen Schülerinnen und Schülern, gegebenenfalls durch Nutzen von Prüfungsunterlagen benachbarter Schulen anderer Schulformen, an der Zentralen Prüfung Englisch zum Mittleren Schulabschluss (Fachoberschulreife) oder zum Erweiterten Ersten Schulabschluss teilzunehmen.</p><p>Bei einer mindestens ausreichenden <strong>Gesamtnote in dieser zusätzlichen Englisch-ZP10</strong> kann auf EESA-Niveau <strong>A2/B1</strong>, auf MSA-Niveau <strong>B1</strong> für Englisch bescheinigt werden. Auf MSA-Niveau ermöglicht dies außerdem die Belegung von Englisch als fortgeführter Fremdsprache in der Oberstufe. Diese Folgen gehören zur Englischprüfung, nicht zur Feststellungsprüfung in der Herkunftssprache.</p><p>Die in der Zentralen Prüfung erreichte Note wird nicht in die Entscheidung über die Versetzung oder die Vergabe der Berechtigung zum Besuch der gymnasialen Oberstufe einbezogen. Gegebenenfalls muss in der EF eine weitere Fremdsprache fortgeführt oder durch Feststellungsprüfung nachgewiesen werden. Rechtsgrundlage: <a href="https://bass.schule.nrw/257.htm" target="_blank" rel="noreferrer">Nummern 10.2 bis 10.4</a>.</p><h2 id="anstelle-der-2-3-fremdsprache" tabindex="-1">Anstelle der 2./3. Fremdsprache <a class="header-anchor" href="#anstelle-der-2-3-fremdsprache" aria-label="Permalink to &quot;Anstelle der 2./3. Fremdsprache&quot;">​</a></h2><h3 id="zeugnis-abschlusszeugnis-oder-versetzungszeugnis-ende-der-si" tabindex="-1">Zeugnis: Abschlusszeugnis oder Versetzungszeugnis Ende der SI <a class="header-anchor" href="#zeugnis-abschlusszeugnis-oder-versetzungszeugnis-ende-der-si" aria-label="Permalink to &quot;Zeugnis: Abschlusszeugnis oder Versetzungszeugnis Ende der SI&quot;">​</a></h3><p>Die Prüfungsnote wird von der Schule, der Einrichtung der Weiterbildung bzw. der besonderen Einrichtung des Schulwesens anstelle der 2. oder 3. Fremdsprache in das Abschlusszeugnis bzw. in das Versetzungszeugnis übertragen. In der Spalte Bemerkungen ist aufzunehmen:</p><pre><code>  &quot;Die Note in _________ wurde aufgrund der Sprachprüfung gemäß RdErl. d. KM v. 10.03.1992 (BASS 13-61 Nr. 1) erteilt.&quot;
</code></pre><h3 id="zeugnis-abschlusszeugnis-und-abgangszeugnis-ende-der-sekundarstufe-i" tabindex="-1">Zeugnis: Abschlusszeugnis und Abgangszeugnis Ende der Sekundarstufe I <a class="header-anchor" href="#zeugnis-abschlusszeugnis-und-abgangszeugnis-ende-der-sekundarstufe-i" aria-label="Permalink to &quot;Zeugnis: Abschlusszeugnis und Abgangszeugnis Ende der Sekundarstufe I&quot;">​</a></h3><p>Tragen Sie nur das nachgewiesene GeR-Niveau nach den geltenden Zeugnisvorgaben ein. Die folgende Bemerkung setzt eine Prüfung auf dem beschriebenen Anspruchsniveau voraus:</p><pre><code>  &quot;Das für SPRACHE ausgewiesene Niveau wurde durch eine Sprachprüfung auf dem Anspruchsniveau des Mittleren Schulabschlusses (Fachoberschulreife) in Klasse 10 erreicht.&quot;
</code></pre><h3 id="zeugnis-abiturzeugnis" tabindex="-1">Zeugnis: Abiturzeugnis <a class="header-anchor" href="#zeugnis-abiturzeugnis" aria-label="Permalink to &quot;Zeugnis: Abiturzeugnis&quot;">​</a></h3><p>Übernehmen Sie unter Fremdsprachen das nachgewiesene GeR-Niveau nach den geltenden Zeugnisvorgaben; B1 ergibt sich nicht pauschal aus jeder Feststellungsprüfung. Die folgende Bemerkung setzt den darin beschriebenen Nachweis voraus:</p><pre><code>  &quot;Das für SPRACHE ausgewiesene Niveau wurde durch eine Sprachprüfung in Klasse 10 erreicht.&quot;
</code></pre><h3 id="prufungsbescheinigung-1" tabindex="-1">Prüfungsbescheinigung <a class="header-anchor" href="#prufungsbescheinigung-1" aria-label="Permalink to &quot;Prüfungsbescheinigung&quot;">​</a></h3><p>Schülerinnen und Schüler, die sich der Sprachprüfung unterzogen haben, erhalten eine <em>Bescheinigung nach dem Muster der Anlage 1 BASS 13-61 Nr. 1</em>.</p><p>Dort ist dokumentiert, an welche Stelle die geprüfte Sprache tritt.</p><p>Die Bescheinigung weist Anspruchsniveau, Ergebnis und ersetzte Fremdsprache aus. Englisch-Nachweise aus einer zusätzlichen ZP10 sind davon zu unterscheiden; siehe <a href="https://bass.schule.nrw/257.htm" target="_blank" rel="noreferrer">BASS 13-61 Nr. 1, Nummern 9 und 10</a>.</p><h2 id="ausnahmen-bei-esa-und-eesa" tabindex="-1">Ausnahmen bei ESA und EESA <a class="header-anchor" href="#ausnahmen-bei-esa-und-eesa" aria-label="Permalink to &quot;Ausnahmen bei ESA und EESA&quot;">​</a></h2><p>Auf eine Sprachprüfung bei Schülerinnen und Schülern kann verzichtet werden, wenn das entsprechende Referenzniveau des Gemeinsamen europäischen Referenzrahmens (GeR) durch ein von einem anerkannten Bildungsträger abgenommenes <strong>Fremdsprachenzertifikat</strong> nachgewiesen wird.</p><ul><li>A2 für den Ersten Schulabschluss (ESA),</li><li>A2/B1 für den Erweiterten Ersten Schulabschluss (EESA) und</li><li>B1 für den Mittleren Schulabschluss (Fachoberschulreife - MSA), der mit der Berechtigung zum Besuch der gymnasialen Oberstufe (MSAQ-E) verbunden sein kann.</li></ul><p>Für den Erwerb des Ersten Schulabschlusses (ESA) und des Erweiterten Ersten Schulabschlusses (EESA) ist die Sprachprüfung in den folgenden Fällen entbehrlich:</p><ul><li>Für Schülerinnen und Schüler, die aus der Klasse 9 oder der Klasse 10 einer Schule des Herkunftslandes unmittelbar in die deutsche Schule eintreten, wird für die Vergabe der vorgenannten Abschlüsse die im Herkunftsland zuletzt erteilte Note für den Unterricht in der Amtssprache des jeweiligen Herkunftslandes übernommen</li><li>Für Schülerinnen und Schüler, die die deutsche Schule erst ab der Klasse 7 oder der Klasse 8 besuchen und bis zum Schulabschluss an einem den Regelunterricht ergänzenden Unterrichtsangebot in der Amtssprache des Herkunftslandes im Umfang von mindestens drei Wochenstunden regelmäßig teilgenommen haben, wird für die Vergabe der vorgenannten Abschlüsse die in diesem Unterricht zuletzt erteilte Note übernommen</li></ul><h3 id="abschlusszeugnis-esa-und-eesa-ende-der-si" tabindex="-1">Abschlusszeugnis ESA und EESA Ende der SI <a class="header-anchor" href="#abschlusszeugnis-esa-und-eesa-ende-der-si" aria-label="Permalink to &quot;Abschlusszeugnis ESA und EESA Ende der SI&quot;">​</a></h3><p>Die Noten werden in diesen entbehrlichen Fällen von der Schule anstelle von Englisch in das Abschlusszeugnis übertragen. In die Spalte Bemerkungen ist aufzunehmen:</p><pre><code>  &quot;Die Note in _________ wurde aufgrund einer Leistung erteilt, die im Herkunftsland / in einem den Regelunterricht ergänzenden Unterrichtsangebot des Landes Nordrhein-Westfalen erbracht wurde.&quot;
</code></pre><h2 id="einstellungen-in-schild-nrw" tabindex="-1">Einstellungen in SchILD-NRW <a class="header-anchor" href="#einstellungen-in-schild-nrw" aria-label="Permalink to &quot;Einstellungen in SchILD-NRW&quot;">​</a></h2><h3 id="unterrichtsfacher" tabindex="-1">Unterrichtsfächer <a class="header-anchor" href="#unterrichtsfacher" aria-label="Permalink to &quot;Unterrichtsfächer&quot;">​</a></h3><p><a href="/bilder/sekundarstufen/tutorials-sprachpruefungen-fach-anlegen.png"><img src="`+u+'" alt="Unterrichtsfach für Festellungsprüfungen (FSP)." loading="lazy"></a></p><p><em>Unterrichtsfach für Festellungsprüfungen (FSP).</em></p><p>Legen Sie ein Fach für die Prüfungssprache an. Gehen Sie hierzu über <em>Kataloge</em> ➜ <strong>Unterrichtsfächer</strong> und legen Sie über das <strong>+</strong> ein Fach mit den folgenden Daten an. Hierbei wird mitunter die Abkürzung FSP genutzt, um die Feststellungsprüfung deutlich zu machen.</p><p>Das folgende Beispiel verwendet Türkisch. Übertragen Sie die Einträge entsprechend auf die tatsächlich geprüfte Sprache.</p><ul><li><strong>ASD-Bezeichnung</strong>: SR - Sonstige Sprache</li><li><strong>Internes Kürzel</strong>: FSP-T</li><li><strong>Bezeichnung</strong>: FSP Türkisch</li><li><strong>Bereich auf dem Zeugnisdruck</strong>: Fremdsprachen</li><li><strong>Bezeichnung im Zeugnis</strong>: Türkisch</li><li><strong>Bezeichnung im Überweisungszeugnis</strong>: Türkisch</li><li>Sonstige Einstellungen zum Anhaken: Haken Sie <strong>Fremdsprache</strong> im Detailbereich an. Dann stellen Sie sicher, dass <strong>auf Zeugnis</strong> und <strong>sichtbar</strong> in der Fachübersichtsliste ebenfalls angehakt sind. Diese beiden Haken sollten aber bei der Facherstellung gesetzt werden.</li><li>Sollte die Feststellungsprüfung in einem Jahrgang vor dem Abschlussjahrgang stattfinden, sollte der Haken bei <em>Abgeschlossene Fächer holen</em> gesetzt werden.</li></ul><p>Legen Sie das Fach mit dem Haken in der Kopfzeile über den Fächern an.</p>',70),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Nach Anlegen des Faches sollte SchILD-NRW neu gestartet werden, damit die Kataloge vollständig neu eingelesen werden.")],-1),r('<h3 id="sprachenfolge" tabindex="-1">Sprachenfolge <a class="header-anchor" href="#sprachenfolge" aria-label="Permalink to &quot;Sprachenfolge&quot;">​</a></h3><p>Tragen Sie das Fach in die Sprachenfolge auf dem Reiter <em>Schüler</em> ➜ <strong>Laufbahninfo</strong> unter <strong>Sprachprüfungen - Feststellungsprüfungen</strong> ein.</p><p>Fügen Sie die Prüfung mit einem <strong>+</strong> hinzu und wählen Sie <em>Herkunftssprache anstelle einer Pflichtsprache - SPRACHE</em> aus.</p><p>Dann ist anzuwählen, welche der nach der APO vorgesehenen Fremdsprachen ersetzt wird, also die <em>1.</em> oder <em>2. Pflichtfremdsprache</em> oder die <em>Wahlpflichtfremdsprache</em>.</p><p>Wählen Sie mit dem Haken an, ob es sich um eine in der <em>Gymnasialen Oberstufe fortgeführte Sprache</em> handelt, dann geben sie den <strong>Jahrgang</strong> an, in dem die Sprachprüfung das Niveau festgestellt hat.</p><p>Unter <strong>Anspruchsniveau</strong> ist das Niveau anzugeben, für welchen Abschluss die Sprachprüfung mit der erreichten Note/Jahrgang/Qualität steht. Relevant ist dies besonders, wenn es um das Erreichen des Qs zum Besuch der gymnasialen Oberstufe geht oder um ein Erfüllen anderer Versetzungskriterien.</p><p>Unter <strong>Note</strong> und <strong>Datum</strong> sind die Ergebnisse dieses Prüfungstages abzulegen. Es sind Noten ohne Tendenzen vorgesehen.</p><p>Erfassen Sie das <strong>Referenzniveau</strong>, soweit es durch die Prüfungsbescheinigung oder die einschlägigen Vorgaben belegt ist. Der GeR ist nicht auf Englisch, Französisch, Spanisch und Deutsch beschränkt. <strong>Anspruchsniveau</strong> des Abschlusses und <strong>GeR-Referenzniveau</strong> sind unterschiedliche Angaben; übernehmen Sie nicht allein aus der Auswahl „MSA“ automatisch „B1“.</p><p><a href="/bilder/sekundarstufen/schueler-sprachenfolgen-fsp.png"><img src="'+l+'" alt="Feststellungsprüfungen in die Sprachenfolge aufnehmen." loading="lazy"></a></p><p><em>Feststellungsprüfungen in die Sprachenfolge aufnehmen.</em></p>',10),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("ul",null,[e("li",null,[n("Fremdsprache: "),e("em",null,"Herkunfssprache anstelle einer Pflichtfremdsprache - Türkisch")]),e("li",null,[n("Ersetzt: "),e("em",null,"2. Pflichtfremdsprache")]),e("li",null,"Fortgeführte Fremdsprache GOSt: ☐"),e("li",null,[n("Jahrgang: "),e("em",null,"09")]),e("li",null,[n("Anspruchsniveau: "),e("em",null,"MSA")]),e("li",null,[n("Note: "),e("em",null,"2")]),e("li",null,"Referenzniveau:"),e("li",null,[n("Prüfungsdatum: "),e("em",null,"07.03.2030")])])],-1),r('<h3 id="leistungsdaten-fur-abschluss-und-versetzungszeugnis" tabindex="-1">Leistungsdaten für Abschluss- und Versetzungszeugnis <a class="header-anchor" href="#leistungsdaten-fur-abschluss-und-versetzungszeugnis" aria-label="Permalink to &quot;Leistungsdaten für Abschluss- und Versetzungszeugnis&quot;">​</a></h3><p><a href="/bilder/sekundarstufen/schueler-fsp-leistungsdaten-fach-hinzufuegen.png"><img src="'+h+`" alt="Fügen Sie das Fach mit der FSP nun den Leistungsdaten des aktuellen Halbjahrs hinzu." loading="lazy"></a></p><p><em>Fügen Sie das Fach mit der FSP nun den Leistungsdaten des aktuellen Halbjahrs hinzu.</em></p><p>Zuerst muss das Fach, mit dem eine Feststellungsprüfung ausgewiesen wird, im <em>Katalog</em> ➜ <strong>Unterrichtsfächer</strong> angelegt sein. Dieser Punkt wurde weiter oben in dieser Anleitung schon beschrieben.</p><p>Nun gilt es, dem Schüler dieses Fach auch in den Leistungsdaten des für den Abschluss relevanten aktuellen Halbjahrs auszuweisen.</p><p>Fügen Sie das zuvor im Katalog angelegte Fach unter <strong>Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten</strong> hinzu.</p><p>Es werden nur <strong>Fach</strong> und <strong>Note</strong> gesetzt, die Daten zum Unterricht wie <strong>Kursart</strong>, <strong>Lehrkraft</strong> oder <strong>Wochenzeiteinheiten</strong> bleiben <em>leer</em>, da kein Unterricht stattfand.</p><p>Setzen Sie auch die <strong>Zeugnisbemerkung</strong>:</p><pre><code> Die Note in Türkisch wurde aufgrund der Sprachprüfung gemäß RdErl. d. KM v. 10.03.1992 (BASS 13-61 Nr. 1) erteilt.
</code></pre><p>Das Beispielfach hier wäre etwa <em>FSP-T</em> oder <em>FSP Türkisch</em>.</p>`,10),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("ul",null,[e("li",null,[n("Fach: "),e("em",null,"FSP Türkisch")]),e("li",null,[n("Auf Zeugnis: "),e("em",null,"Aktiviert")]),e("li",null,"Kursart: leer"),e("li",null,"Lehrkraft: leer"),e("li",null,[n("Note: "),e("em",null,"2")]),e("li",null,"Wochenzeiteinheit: leer")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sprachpr%C3%BCfung_Feststellungspr%C3%BCfung_anstelle_von_Pflicht-_oder_Wahlpflichtfremdsprachen_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6084.")],-1)])])}const S=i(d,[["render",g]]);export{z as __pageData,S as default};
